def hungarian_extension():
    from itertools import combinations, permutations
    a=[[82,83,69,92],[77,37,49,92],[11,69,5,86],[8,9,98,23]]
    row=[min(x)for x in a];b=[[x-row[i]for x in r]for i,r in enumerate(a)];col=[min(r[j]for r in b)for j in range(4)];b=[[x-col[j]for j,x in enumerate(r)]for r in b]
    steps=['Subtract row minima '+str(row)+' and column minima '+str(col)+'. Initial reduced matrix: '+mat(b)]
    def independent(b):return [p for p in permutations(range(4))if all(b[i][p[i]]==0 for i in range(4))]
    while not independent(b):
        zeros=[(i,j)for i in range(4)for j in range(4)if b[i][j]==0];cover=None
        for count in range(5):
            for lines in combinations(range(8),count):
                if all(i in lines or j+4 in lines for i,j in zeros):cover=lines;break
            if cover is not None:break
        rows=[x for x in cover if x<4];cols=[x-4 for x in cover if x>=4];delta=min(b[i][j]for i in range(4)for j in range(4)if i not in rows and j not in cols)
        steps.append(f'Minimum zero cover uses rows {[i+1 for i in rows]} and columns {[j+1 for j in cols]}; {len(cover)} lines < 4. Smallest uncovered entry = {delta}.')
        b=[[b[i][j]-delta if i not in rows and j not in cols else b[i][j]+delta if i in rows and j in cols else b[i][j]for j in range(4)]for i in range(4)]
        steps.append('Subtract from uncovered cells, add at twice-covered intersections, leave singly covered cells unchanged: '+mat(b))
    p=independent(b)[0];cost=sum(a[i][p[i]]for i in range(4));steps.append('Choose independent zeros: '+', '.join(f'worker {i+1}→job {p[i]+1}'for i in range(4))+f'. Original cost = {cost}. Four independent zeros in a nonnegative reduced array prove optimality.')
    assert cost==min(sum(a[i][p[i]]for i in range(4))for p in permutations(range(4)))
    return task('Use the Hungarian algorithm, including any zero-cover adjustment, for this four-worker/four-job minimisation. Rows and columns are numbered 1–4. Show your original-cost total: '+mat(a),*steps)

def build():
    year11();year12()
    add_extensions()
    ids=[m['id']for m in LESSONS];assert len(ids)==len(set(ids))
    ROOT.joinpath('applications-atar-course.js').write_text('/* Original Applications lessons; generated by build-applications.py. */\nwindow.ApplicationsATAR = '+json.dumps(LESSONS,ensure_ascii=False,separators=(',',':'))+';\n')
    totals={y:sum(m['year']==y for m in LESSONS)for y in ['11','12']}
    print(dict(lessons=len(LESSONS),years=totals,screens=sum(len(m['screens'])for m in LESSONS),questions=sum(len(m['questions'])for m in LESSONS)))

if __name__=='__main__':build()
